INSERT INTO courses (title, description, full_description, price, currency, is_published, pdf_path) VALUES
('Création de Site Web Complet', 'Devenez développeur web de A à Z.', 'Formation complète pour créer des sites web modernes et responsives. Maîtrisez HTML5, CSS3, JavaScript et React. Construisez des sites professionnels from scratch : pages de présentation, portfolios, landing pages et boutiques en ligne. 25h de vidéos HD, projets guidés étape par étape, exercices corrigés, accès à vie et attestation RIVO reconnue par les employeurs africains.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/001_creation-de-site-web-complet.pdf'),
('Marketing Digital et Réseaux Sociaux', 'Maîtrisez Facebook, Instagram, TikTok et WhatsApp.', 'Stratégies marketing digital complètes adaptées au marché africain. Créez des publicités Facebook Ads et Instagram Ads ciblées, produisez du contenu viral sur TikTok, vendez via WhatsApp Business avec des scripts éprouvés. Comprend 30h de vidéos HD, études de cas d''entrepreneurs africains, templates prêts à l''emploi, scripts de vente et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/002_marketing-digital-et-reseaux-sociaux.pdf'),
('Excel du Débutant à l''''Expert', 'Dominez les tableurs, formules et graphiques.', 'Formation Excel exhaustive allant des bases aux macros VBA. Maîtrisez RECHERCHEV, SI, SOMME.SI, les tableaux croisés dynamiques et les graphiques professionnels. Apprenez à automatiser vos tâches répétitives et à créer des tableaux de bord dynamiques. 20h de vidéos HD, 50 exercices avec corrigés, fichiers pratiques téléchargeables et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/003_excel-du-debutant-a-lexpert.pdf'),
('Montage Vidéo CapCut et Premiere Pro', 'Créez des vidéos professionnelles pour les réseaux.', 'Maîtrisez le montage vidéo de A à Z : CapCut pour les créations mobiles rapides, Adobe Premiere Pro pour un rendu cinématographique. Transitions tendance, colorimétrie professionnelle, texte animé, sous-titres automatiques et export optimisé pour chaque réseau. 30h de vidéos, banque de 500 sons gratuits, templates et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/004_montage-video-capcut-et-premiere-pro.pdf'),
('Couture et Stylisme Africain Moderne', 'Créez des vêtements de A à Z, du patron à la vente.', 'Formation couture complète centrée sur les tenues africaines : boubou, pagne, kaba, robes et chemises modernes. Du tracé du patron jusqu''à la vente de vos créations. Apprenez à prendre des mesures, couper et assembler les tissus wax, bazin et soie. 40h de vidéos HD, 50 patrons téléchargeables, 100 photos étape par étape et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/005_couture-et-stylisme-africain-moderne.pdf'),
('Coiffure et Tresse Africaine Pro', 'Maîtrisez toutes les techniques de coiffure.', 'Formation professionnelle en coiffure africaine couvrant toutes les techniques : nattes plaquées, box braids, knotless braids, vanilles, crochet braids, mèches, perruques frontales et soins capillaires naturels. Vidéos tournées en salon professionnel. 35h de vidéos HD, 200 photos de démonstration, liste de fournisseurs de produits et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/006_coiffure-et-tresse-africaine-pro.pdf'),
('Photographie Pro avec Téléphone', 'Photos professionnelles uniquement avec votre smartphone.', 'Devenez photographe professionnel sans équipement coûteux. Maîtrisez les réglages manuels de votre smartphone (ISO, vitesse, ouverture), les règles de composition, la lumière naturelle et artificielle. Retouchez avec Lightroom Mobile et Snapseed comme un pro. 20h de vidéos, 50 presets offerts, guide des accessoires abordables et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/007_photographie-pro-avec-telephone.pdf'),
('Création d''''Entreprise en Afrique', 'Lancez votre business de A à Z sans vous tromper.', 'Tout ce qu''il faut pour créer et développer une entreprise en Afrique : validation d''idée, étude de marché, business plan, statuts juridiques, financement (tontine, microcrédit, subventions) et premières ventes. Interviews d''entrepreneurs africains à succès, modèles de documents juridiques et financiers téléchargeables et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/008_creation-dentreprise-en-afrique.pdf'),
('E-commerce et Dropshipping', 'Vendez en ligne sans stock de marchandise.', 'Créez votre boutique en ligne rentable sans stocker de marchandises. Dropshipping adapté à l''Afrique : fournisseurs locaux et AliExpress, boutique WhatsApp/Instagram/Shopify, paiement Mobile Money (Wave, Orange Money), gestion des livraisons et du service client. Templates prêts à l''emploi, liste de 50 fournisseurs fiables et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/009_e-commerce-et-dropshipping.pdf'),
('Anglais Pratique pour le Travail', 'Anglais utile pour entretiens, emails et voyages.', 'Apprenez l''anglais professionnel adapté aux Africains francophones. Conversations d''affaires, vocabulaire business, rédaction d''emails professionnels, réussite en entretien d''embauche et prononciation travaillée avec un locuteur natif. 30h de vidéos HD, 200 exercices audio, fiches thématiques téléchargeables et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/010_anglais-pratique-pour-le-travail.pdf'),
('Éducation Financière et Investissement', 'Gérez votre argent et créez des revenus passifs.', 'Formation complète en gestion financière personnelle et investissement adaptée à la réalité africaine. Budgétisation (méthode 50/30/20), épargne d''urgence, bourse (BRVM), immobilier et cryptomonnaies. Calculateurs Excel inclus, guide des applications financières disponibles en Afrique et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/011_education-financiere-et-investissement.pdf'),
('Infographie et Design Graphique Pro', 'Créez logos, affiches, flyers et cartes de visite.', 'Maîtrisez Canva et Adobe Illustrator pour produire des visuels professionnels : logos, affiches événementielles, flyers promotionnels, cartes de visite, bannières web et supports de communication. Formation orientée débouchés freelance et agences de communication. 25h de vidéos, 200 templates modifiables et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/012_infographie-et-design-graphique-pro.pdf'),
('Mécanique Auto et Entretien Véhicule', 'Réparez votre voiture et économisez sur les réparations.', 'Formez-vous à la mécanique automobile pour réaliser vos propres entretiens et diagnostiquer les pannes. Vidange, filtres, freins, embrayage, courroie de distribution, batterie et climatisation expliqués en vidéos sous le capot sur des véhicules réels. 25h de vidéos, checklist d''entretien, guide des prix de pièces en Afrique et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/013_mecanique-auto-et-entretien-vehicule.pdf'),
('Agriculture et Élevage Moderne', 'Poulet, poisson, légumes, escargots, abeilles.', 'Formation agricole complète adaptée à l''Afrique subsaharienne : maraîchage intensif, aviculture (poulets de chair et pondeuses), pisciculture (tilapia, catfish), élevage d''escargots géants et apiculture. Techniques de prévention et traitement des maladies animales. 35h de vidéos terrain, fiches techniques par filière et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/014_agriculture-et-elevage-moderne.pdf'),
('Pâtisserie et Cake Design', 'Gâteaux d''''anniversaire, cupcakes et entremets.', 'Devenez pâtissier professionnel avec des recettes adaptées aux ingrédients disponibles en Afrique. Maîtrisez les génoises, crèmes, cake design en fondant, gâteaux à étages, drip cakes et maquillage pour mariages et anniversaires. 30h de vidéos HD, 100 recettes détaillées, 200 photos étape par étape et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/015_patisserie-et-cake-design.pdf'),
('Community Management Pro', 'Gérez les réseaux sociaux d''''une entreprise.', 'Devenez community manager professionnel : élaborez des stratégies de contenu, rédigez des posts engageants pour chaque plateforme, analysez les statistiques et KPI, et produisez des rapports mensuels pour vos clients. Formation orientée freelance avec exemples réels d''entreprises africaines. 20h de vidéos, templates de calendrier éditorial et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/016_community-management-pro.pdf'),
('Électricité Bâtiment et Domestique', 'Installez et réparez les installations électriques.', 'Formation complète en électricité du bâtiment : lecture de schémas, installation d''un tableau électrique (disjoncteurs, différentiels), pose de prises et interrupteurs, éclairage LED, normes de sécurité NFC 15-100. Vidéos tournées sur de vrais chantiers africains. 25h de vidéos, schémas téléchargeables, checklist de sécurité et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/017_electricite-batiment-et-domestique.pdf'),
('Création de Contenu Viral', 'Devenez créateur de contenu sur TikTok et Instagram.', 'Maîtrisez la création de contenu viral sur TikTok et Instagram Reels : compréhension des algorithmes, hooks puissants en 3 secondes, storytelling vidéo, hashtags stratégiques et monétisation. 50 exemples de vidéos virales analysées, templates de scripts, guide de monétisation (Creator Fund, partenariats, produits numériques) et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/018_creation-de-contenu-viral.pdf'),
('Programmation Python et IA', 'Initiez-vous au langage le plus demandé au monde.', 'Apprenez Python de zéro jusqu''à l''intelligence artificielle : variables, boucles, fonctions, bibliothèques NumPy/Pandas/Matplotlib, Machine Learning avec Scikit-learn. Créez votre premier modèle prédictif et préparez une carrière en data science. 25h de vidéos HD, 100 exercices corrigés, code source complet téléchargeable et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/019_programmation-python-et-ia.pdf'),
('Gestion de Projet Agile Scrum', 'Maîtrisez la méthodologie Scrum en entreprise.', 'Maîtrisez le framework Scrum : rôles (Product Owner, Scrum Master, équipe), artefacts (product backlog, sprint backlog, increment) et cérémonies (sprint planning, daily scrum, review, retrospective). Outils Jira et Trello. Préparation à la certification PSM I. 15h de vidéos, templates prêts à l''emploi et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/020_gestion-de-projet-agile-scrum.pdf'),
('Service Client et Relation Client', 'Fidélisez vos clients et gérez les réclamations.', 'Formation pratique au service client d''excellence : communication empathique, gestion des réclamations et clients difficiles, scripts d''accueil téléphonique et d''email, CRM basique (HubSpot gratuit), mesure de la satisfaction (NPS, CSAT). Idéale pour commerciaux, agents d''accueil et entrepreneurs. 10h de vidéos, modèles d''emails et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/021_service-client-et-relation-client.pdf'),
('Sécurité Informatique et Cybersécurité', 'Protégez vos données contre les pirates.', 'Protégez-vous et votre entreprise contre les cyberattaques les plus courantes en Afrique : phishing, ransomware, arnaques téléphoniques, mots de passe faibles, WiFi non sécurisé. Authentification à deux facteurs, VPN, gestionnaire de mots de passe, chiffrement et sauvegarde. 20h de vidéos HD, checklist de sécurité, guide des outils gratuits et attestation RIVO.', 9000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/022_securite-informatique-et-cybersecurite.pdf'),
('Bourse et Trading pour Débutants', 'Apprenez à investir en bourse depuis votre téléphone.', 'Formation au trading boursier pour débutants : marchés financiers (actions, ETF, forex), bourse africaine BRVM, analyse technique (chandeliers, supports/résistances, RSI, MACD), gestion du risque (stop-loss, ratio risque/rendement) et tenue d''un journal de trading. 20h de vidéos, simulateur de trading, guide des applications mobiles et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/023_bourse-et-trading-pour-debutants.pdf'),
('Rédaction Web et Copywriting', 'Écrivez des textes qui vendent et attirent les clients.', 'Apprenez à rédiger des textes web optimisés SEO et des textes de vente persuasifs. Formules de copywriting (AIDA, PAS, 4P), pages de vente, emails marketing, articles de blog, descriptions produits. Formation orientée freelance avec 50 exemples commentés, templates prêts à l''emploi, guide Fiverr/Upwork et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/024_redaction-web-et-copywriting.pdf'),
('Décoration d''''Intérieur', 'Transformez n''''importe quel espace en lieu magnifique.', 'Formation en décoration d''intérieur adaptée aux espaces et budgets africains. Harmonie des couleurs, choix des matières et meubles, éclairage d''ambiance, home staging pour la valorisation immobilière. Création de moodboards, simulation 3D avec Planner 5D. 15h de vidéos, 100 photos de réalisations, guide des fournisseurs locaux et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/025_decoration-dinterieur.pdf'),
('Maquillage Professionnel Complet', 'Du maquillage naturel au maquillage artistique.', 'Formation complète en maquillage adaptée aux carnations et types de peau africaines. Préparation de la peau, fond de teint, contouring, smoky eye, maquillage de mariée et looks créatifs. 100 photos de démonstration sur différentes carnations, liste des meilleurs produits disponibles en Afrique et guide pour lancer son activité de maquilleuse. Attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/026_maquillage-professionnel-complet.pdf'),
('Puériculture et Garde d''''Enfants', 'Devenez nounou professionnelle certifiée.', 'Formation complète en puériculture et garde d''enfants pour travailler en crèche, à domicile ou créer sa propre garderie. Soins du nourrisson, alimentation (allaitement, diversification), activités d''éveil, sécurité, prévention des accidents et premiers secours pédiatriques. 15h de vidéos HD, guide pratique pédiatrique illustré et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/027_puericulture-et-garde-denfants.pdf'),
('Logistique et Gestion des Stocks', 'Organisez votre stock et vos livraisons efficacement.', 'Maîtrisez la logistique et la gestion des stocks pour votre commerce ou entreprise. Organisation physique de l''entrepôt, suivi des stocks (FIFO, stock minimum, stock de sécurité), inventaires, choix des transporteurs africains et optimisation des coûts logistiques. 12h de vidéos, templates Excel de gestion des stocks et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/028_logistique-et-gestion-des-stocks.pdf'),
('Formation de Formateur', 'Apprenez à transmettre votre savoir et créer des cours.', 'Devenez formateur professionnel capable de créer et d''animer des formations en présentiel ou en ligne. Pédagogie adulte, conception de programmes, création de supports percutants, animation de groupe, gestion des profils difficiles, évaluation des apprenants et vente de formations. 15h de vidéos, templates et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/029_formation-de-formateur.pdf'),
('Menuiserie et Fabrication de Meubles', 'Fabriquez vos propres meubles en bois.', 'Formez-vous à la menuiserie pour fabriquer tables, chaises, armoires et meubles sur mesure. Choix des bois, outils (scie, rabot, défonceuse), assemblages (tenon-mortaise, domino), finitions et vernissage. Vidéos tournées en atelier de menuiserie professionnel. 25h de vidéos, plans téléchargeables pour 20 modèles de meubles et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/030_menuiserie-et-fabrication-de-meubles.pdf'),
('Saponification et Cosmétiques Naturels', 'Fabriquez savons, crèmes et produits de beauté.', 'Fabriquez vos propres cosmétiques naturels avec des ingrédients africains : savons au beurre de karité, crèmes hydratantes à l''huile de coco, baumes à lèvres, huiles capillaires et déodorants naturels. Saponification à froid, formulation cosmétique de base. 15h de vidéos, 30 recettes naturelles, liste de fournisseurs africains et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/031_saponification-et-cosmetiques-naturels.pdf'),
('Podcast et Audio Digital', 'Créez votre podcast et touchez des milliers d''''auditeurs.', 'Lancez et développez votre podcast professionnel sur Spotify, Apple Podcasts et Deezer. Définir son concept, enregistrer avec un micro abordable, monter avec Audacity, créer une couverture attractive et promouvoir sur les réseaux. 10h de vidéos HD, guide du matériel audio abordable en Afrique et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/032_podcast-et-audio-digital.pdf'),
('Gestion de Crise et Communication', 'Protégez votre réputation en situation difficile.', 'Apprenez à anticiper, gérer et sortir renforcé d''une crise de communication. Bad buzz sur les réseaux sociaux, plaintes clients virales, incidents médiatiques, excuses publiques et rétablissement de la confiance. Études de cas concrets d''entreprises africaines. 10h de vidéos, protocole de gestion de crise personnalisable et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/033_gestion-de-crise-et-communication.pdf'),
('Maintenance Informatique et Réparation', 'Réparez ordinateurs et smartphones.', 'Devenez technicien en maintenance informatique : diagnostic et réparation d''ordinateurs (remplacement disque dur, RAM, clavier, écran) et smartphones (écran cassé, batterie, connecteur de charge, soudure micro). Réinstallation Windows/Linux, récupération de données. 20h de vidéos, guide des pièces détachées en Afrique et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/034_maintenance-informatique-et-reparation.pdf'),
('Marketing d''''Affiliation', 'Gagnez des commissions en recommandant des produits.', 'Créez des revenus passifs grâce au marketing d''affiliation : rejoindre des programmes africains et internationaux, créer du contenu qui convertit (articles, vidéos, réseaux sociaux), optimiser ses liens d''affiliation et analyser ses performances. 10h de vidéos, liste de 50 programmes d''affiliation rentables et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/035_marketing-daffiliation.pdf'),
('Production Musicale FL Studio', 'Créez vos propres beats et instrumentales.', 'Maîtrisez FL Studio pour produire des beats Afrobeats, coupé-décalé, Afropop et musiques africaines tendance. Mélodies, drum patterns, plugins VST, mixage professionnel et mastering. Exporter et vendre vos productions en ligne. 20h de vidéos HD, 50 samples exclusifs, projets FL Studio téléchargeables et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/036_production-musicale-fl-studio.pdf'),
('Tourisme et Hôtellerie', 'Formation aux métiers de l''''accueil et du tourisme.', 'Formation complète aux métiers du tourisme et de l''hôtellerie en Afrique : techniques d''accueil, service en salle, réservations et conciergerie, guidage touristique, vente de séjours et gestion d''une maison d''hôtes. Simulation de situations réelles, documents types téléchargeables et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/037_tourisme-et-hotellerie.pdf'),
('Dessin Artistique et Illustration', 'Du croquis à l''''œuvre aboutie.', 'Apprenez le dessin artistique de A à Z : proportions humaines, ombres et lumière, textures, perspectives et dessin numérique (Procreate, Ibis Paint X). Portraits, personnages, paysages et illustration pour les réseaux sociaux. 20h de vidéos progressives, 100 exercices corrigés, ressources gratuites et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/038_dessin-artistique-et-illustration.pdf'),
('Plantes Médicinales et Remèdes Naturels', 'Découvrez le pouvoir des plantes africaines.', 'Plongez dans la phytothérapie africaine : moringa, neem, bissap, kinkeliba, gingembre, citronnier et bien d''autres. Reconnaissance des plantes, récolte, séchage, préparation de décoctions, tisanes, pommades et huiles essentielles maison. 15h de vidéos terrain, 50 fiches plantes illustrées et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/039_plantes-medicinales-et-remedes-naturels.pdf'),
('Vente Directe et Négociation', 'Maîtrisez l''''art de la vente en face à face.', 'Devenez un vendeur d''élite : prospection ciblée, premier contact percutant, présentation convaincante du produit, gestion des objections (trop cher, j''y réfléchis), conclusion et fidélisation. Scripts de vente adaptés au contexte africain, roleplay et mises en situation. 10h de vidéos, scripts audio et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/040_vente-directe-et-negociation.pdf'),
('CV et Lettre de Motivation Percutants', 'Décrochez plus d''''entretiens avec un CV pro.', 'Créez un CV et une lettre de motivation qui passent les filtres ATS et marquent les recruteurs. Structure optimale, mots-clés par secteur, adaptation à chaque offre, format PDF professionnel. 5h de vidéos pratiques, 20 templates téléchargeables (Word et Canva), exemples par métier et attestation RIVO.', 2000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/041_cv-et-lettre-de-motivation-percutants.pdf'),
('Langue Portugaise pour les Affaires', 'Commercez avec le Brésil, Portugal et Angola.', 'Apprenez le portugais des affaires pour développer vos relations commerciales avec le Brésil, le Portugal, l''Angola et le Mozambique. Vocabulaire business, conversations professionnelles, négociation, correspondance et présentation. 15h de vidéos, exercices audio, fiches de vocabulaire thématiques et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/042_langue-portugaise-pour-les-affaires.pdf'),
('Apiculture et Production de Miel', 'Élevez des abeilles et vendez votre miel.', 'Lancez votre activité apicole de A à Z : choix de la ruche (Langstroth ou kenyane), installation, entretien des colonies, traitement varroa, récolte et extraction du miel, mise en pot et commercialisation. Calendrier apicole africain, guide des plantes mellifères locales et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/043_apiculture-et-production-de-miel.pdf'),
('Google Ads et Publicité en Ligne', 'Créez des campagnes publicitaires qui convertissent.', 'Maîtrisez Google Ads de A à Z : Search Ads, Display Ads, YouTube Ads et retargeting. Recherche de mots-clés, enchères intelligentes, Quality Score, extensions d''annonces, suivi des conversions et optimisation continue. 15h de vidéos, compte démo pratique, templates de campagnes et attestation RIVO.', 9000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/044_google-ads-et-publicite-en-ligne.pdf'),
('Facebook Ads et Instagram Ads', 'Publicités ciblées sur les réseaux Meta.', 'Créez des campagnes publicitaires performantes sur Facebook et Instagram. Audiences personnalisées et lookalike, formats créatifs (image, vidéo, carrousel, collection), budget et enchères, pixel Meta, A/B testing et analyse des résultats. 15h de vidéos, templates de visuels, guide de ciblage africain et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/045_facebook-ads-et-instagram-ads.pdf'),
('SEO et Référencement Naturel', 'Soyez visible sur Google sans payer de publicité.', 'Apprenez le SEO complet pour positionner votre site en première page Google sans budget publicitaire. Recherche de mots-clés, optimisation on-page, création de backlinks, SEO technique (vitesse, mobile, Core Web Vitals), SEO local et audit complet. 15h de vidéos, checklist SEO téléchargeable, outils gratuits et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/046_seo-et-referencement-naturel.pdf'),
('Adobe Photoshop Complet', 'Retouche photo et création graphique professionnelle.', 'Maîtrisez Adobe Photoshop de zéro à avancé : calques et masques, retouche portrait (peau, yeux, silhouette), détourage professionnel, photomontages créatifs, création d''affiches et de bannières. Idéal pour photographes, graphistes et créatifs. 25h de vidéos, 100 exercices progressifs, ressources PSD et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/047_adobe-photoshop-complet.pdf'),
('Adobe Illustrator Complet', 'Dessin vectoriel et création de logos.', 'Créez des logos, illustrations et identités visuelles professionnelles avec Adobe Illustrator. Courbes de Bézier, Pathfinder, typographie créative, systèmes de couleurs (Pantone, CMJN, RVB), export pour print et web. 20h de vidéos, 50 exercices progressifs, création d''une identité visuelle complète et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/048_adobe-illustrator-complet.pdf'),
('Adobe Premiere Pro Complet', 'Montage vidéo professionnel pour le cinéma et le web.', 'Formation professionnelle Adobe Premiere Pro : timeline multicaméra, effets vidéo et transitions, mixage audio avancé, étalonnage colorimétrique (Lumetri), sous-titres, export. Projets réels incluant clip musical, court-métrage et publicité. 25h de vidéos HD, projets téléchargeables et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/049_adobe-premiere-pro-complet.pdf'),
('After Effects et Motion Design', 'Créez des animations et effets visuels.', 'Créez des animations graphiques et effets visuels professionnels avec After Effects. Keyframes, expressions, compositing, particules, explosions VFX, génériques de films, infographies animées et motion design pour les réseaux sociaux. 20h de vidéos HD, templates premium offerts, assets AEP et attestation RIVO.', 9000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/050_after-effects-et-motion-design.pdf'),
('Canva pour les Réseaux Sociaux', 'Créez tous vos visuels facilement et rapidement.', 'Maîtrisez Canva pour créer tous vos visuels en quelques minutes : posts Instagram/Facebook, stories, reels animés, bannières YouTube, présentations, CVs, flyers, cartes de visite et catalogues. Brand Kit, animations, suppression de fond. 10h de vidéos, 100 templates personnalisés offerts et attestation RIVO.', 2000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/051_canva-pour-les-reseaux-sociaux.pdf'),
('Figma et UI/UX Design', 'Design d''''interfaces web et mobile.', 'Devenez UI/UX designer avec Figma : wireframes basse et haute fidélité, prototypes interactifs, design system, grilles et espacements, tests utilisateurs. Projets réels : application mobile et site web e-commerce. 20h de vidéos, fichiers Figma téléchargeables, préparation aux entretiens UX et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/052_figma-et-ui-ux-design.pdf'),
('Blender et Modélisation 3D', 'Créez des objets 3D pour le jeu vidéo et l''''animation.', 'Maîtrisez Blender 4 pour la modélisation 3D : modélisation polygonale, sculpting, UV mapping, textures PBR, rigging, animation, éclairage HDRI et rendu Cycles/EEVEE. Projets : personnage animé, objet pour impression 3D, scène architecturale. 25h de vidéos, assets gratuits et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/053_blender-et-modelisation-3d.pdf'),
('Kotlin et Développement Android', 'Créez des applications mobiles Android natives.', 'Développez des applications Android professionnelles en Kotlin. Activities et fragments, RecyclerView, navigation Component, Room Database, Retrofit API, Firebase (Auth, Firestore, Notifications push) et publication sur le Play Store. 3 projets complets, 30h de vidéos HD et attestation RIVO.', 10000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/054_kotlin-et-developpement-android.pdf'),
('Swift et Développement iOS', 'Créez des applications iPhone et iPad.', 'Développez des applications iOS professionnelles avec Swift et SwiftUI. NavigationView, CoreData, URLSession, animations, ARKit, notifications push et publication sur l''''App Store. 3 applications complètes du débutant au déploiement. 30h de vidéos HD, projets Xcode téléchargeables et attestation RIVO.', 10000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/055_swift-et-developpement-ios.pdf'),
('Flutter et Apps Multi-plateformes', 'Un seul code pour Android et iOS.', 'Créez une application unique qui fonctionne sur Android et iOS avec Flutter (langage Dart). Widgets personnalisés, state management (Provider et Bloc), Firebase, API REST, animations fluides et déploiement sur les deux stores. 25h de vidéos, 2 projets complets et attestation RIVO.', 9000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/056_flutter-et-apps-multi-plateformes.pdf'),
('React JS et Applications Web Modernes', 'Développez des interfaces web dynamiques.', 'Maîtrisez React.js pour créer des interfaces web modernes et performantes. Composants fonctionnels, hooks (useState, useEffect, useContext), Redux Toolkit, React Router, appels API REST et déploiement. 3 projets pratiques dont un dashboard complet. 25h de vidéos HD et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/057_react-js-et-applications-web-modernes.pdf'),
('Node JS et Backend JavaScript', 'Créez des serveurs et APIs avec JavaScript.', 'Développez des APIs RESTful robustes avec Node.js et Express. MongoDB avec Mongoose, authentification JWT, upload de fichiers, gestion des erreurs, tests unitaires et déploiement sur VPS Linux. 2 projets backend complets. 25h de vidéos, code source téléchargeable et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/058_node-js-et-backend-javascript.pdf'),
('PHP et MySQL pour le Web', 'Développement backend avec PHP et bases de données.', 'Créez des applications web dynamiques avec PHP 8 et MySQL. CRUD complet, sessions et cookies, sécurité web (injection SQL, XSS, CSRF), APIs REST, POO en PHP. Projet final : plateforme e-commerce opérationnelle. 25h de vidéos HD, code source complet et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/059_php-et-mysql-pour-le-web.pdf'),
('WordPress et Création de Sites', 'Créez des sites sans coder avec WordPress.', 'Créez des sites web professionnels sans écrire une ligne de code avec WordPress. Thèmes Elementor et Divi, plugins essentiels, boutique WooCommerce, SEO Yoast, sécurité (Wordfence) et sauvegardes. 15h de vidéos, templates premium inclus, guide d''''hébergement africain et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/060_wordpress-et-creation-de-sites.pdf'),
('Data Science et Analyse de Données', 'Exploitez les données pour prendre des décisions.', 'Maîtrisez la data science avec Python : manipulation de données (Pandas), statistiques descriptives et inférentielles, visualisation (Matplotlib, Seaborn, Plotly), Machine Learning (Scikit-learn) et présentation de résultats. Datasets réels africains (agriculture, finance, santé). 25h de vidéos, notebooks Jupyter et attestation RIVO.', 9000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/061_data-science-et-analyse-de-donnees.pdf'),
('Power BI et Visualisation de Données', 'Créez des tableaux de bord interactifs.', 'Créez des tableaux de bord professionnels et interactifs avec Power BI Desktop et Service. Import et transformation de données (Power Query), modélisation, langage DAX, visualisations avancées, partage et collaboration. 15h de vidéos, exercices avec données réelles d''''entreprises africaines et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/062_power-bi-et-visualisation-de-donnees.pdf'),
('SQL et Bases de Données', 'Maîtrisez le langage des bases de données.', 'Maîtrisez SQL de A à Z avec MySQL et PostgreSQL : SELECT avancé, JOIN multiples, GROUP BY, sous-requêtes corrélées, vues, index, procédures stockées et triggers. Optimisation des requêtes pour de grandes bases de données. 15h de vidéos, 100 exercices progressifs avec corrigés et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/063_sql-et-bases-de-donnees.pdf'),
('Linux et Administration Serveur', 'Gérez des serveurs Linux comme un pro.', 'Administrez des serveurs Linux Ubuntu/CentOS : commandes de base et avancées, scripting bash, gestion des utilisateurs et permissions, services (Apache, Nginx, MySQL), sécurité SSH, pare-feu (UFW) et monitoring. 20h de vidéos, machine virtuelle de pratique fournie et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/064_linux-et-administration-serveur.pdf'),
('Cloud Computing AWS', 'Déployez vos applications sur Amazon Web Services.', 'Maîtrisez Amazon Web Services : EC2 (serveurs virtuels), S3 (stockage), RDS (bases de données), Lambda (serverless), IAM (sécurité), VPC (réseau) et CloudWatch (monitoring). Préparation à la certification AWS Cloud Practitioner. 25h de vidéos, labs pratiques avec compte AWS gratuit et attestation RIVO.', 10000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/065_cloud-computing-aws.pdf'),
('Blockchain et Web3', 'Comprenez la technologie qui change le monde.', 'Comprenez et développez sur la blockchain : fonctionnement du Bitcoin et d''''Ethereum, smart contracts en Solidity, NFTs, DeFi (finance décentralisée), portefeuilles crypto et sécurité. Créez et déployez votre premier smart contract sur testnet. 20h de vidéos, démos pratiques et attestation RIVO.', 9000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/066_blockchain-et-web3.pdf'),
('Développement de Jeux Vidéo Unity', 'Créez votre premier jeu vidéo avec Unity et C#.', 'Développez votre premier jeu vidéo professionnel avec Unity et C#. Scènes et GameObjects, physique Rigidbody, UI Canvas, animations, particules VFX, audio, intelligence artificielle simple et build pour Android, iOS et PC. 3 jeux complets. 30h de vidéos, assets gratuits inclus et attestation RIVO.', 10000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/067_developpement-de-jeux-video-unity.pdf'),
('Drones : Pilotage et Photographie Aérienne', 'Pilotez un drone et prenez des photos aériennes pros.', 'Apprenez à piloter un drone légalement et à réaliser des photos et vidéos aériennes professionnelles. Réglementation africaine, techniques de vol (ascension, panoramique, orbit), cadrage aérien, retouche de photos drone et montage de séquences aériennes. 10h de vidéos, checklist de sécurité et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/068_drones-pilotage-et-photographie-aerienne.pdf'),
('Énergie Solaire et Installation', 'Installez des panneaux solaires et générez de l''''électricité.', 'Installez des systèmes solaires photovoltaïques autonomes ou en réseau. Dimensionnement (puissance, batteries, régulateur MPPT), câblage, installation de panneaux, onduleurs et maintenance préventive. Formation très demandée en Afrique. 20h de vidéos, schémas électriques téléchargeables et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/069_energie-solaire-et-installation.pdf'),
('Climatisation et Froid Industriel', 'Installez et réparez les systèmes de climatisation.', 'Maîtrisez les systèmes de climatisation split et multi-split : diagnostic des pannes, charge de gaz réfrigérant (R410A, R32), brasure, câblage, entretien préventif et réglages. Froid industriel : chambres froides, vitrines réfrigérées. 20h de vidéos, guide technique des fluides frigorigènes et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/070_climatisation-et-froid-industriel.pdf'),
('Plomberie et Tuyauterie', 'Réparez et installez les systèmes d''''eau.', 'Réalisez vos propres installations de plomberie et dépannez les fuites. Tuyaux PER, PVC et cuivre, robinetterie, chauffe-eau électrique et solaire, évacuation, détartrage et fosse septique. 20h de vidéos sur chantiers réels, schémas d''''installation téléchargeables et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/071_plomberie-et-tuyauterie.pdf'),
('Soudure et Métallerie', 'Travaillez le métal : soudure à l''''arc, MIG, TIG.', 'Maîtrisez les techniques de soudure : soudure à l''''arc électrique (MMA), MIG/MAG pour la carrosserie et TIG pour la précision. Sécurité, préparation des pièces, techniques d''''assemblage, distorsions thermiques et finitions (meulage, peinture). 20h de vidéos en atelier professionnel et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/072_soudure-et-metallerie.pdf'),
('Conduite Automobile et Code de la Route', 'Préparez votre permis de conduire théorique et pratique.', 'Préparez et réussissez votre permis de conduire : panneaux de signalisation, règles de priorité, code de la route africain, conduite défensive, prévention des accidents et éco-conduite. 15h de vidéos animées, tests en ligne illimités, fiches mémo téléchargeables et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/073_conduite-automobile-et-code-de-la-route.pdf'),
('Mécanique Moto et Entretien', 'Réparez et entretenez votre moto vous-même.', 'Économisez sur l''''entretien de votre moto : vidange, filtres, réglage du carburateur, remplacement des freins (plaquettes et disques), pneus, chaîne, embrayage et électricité. Adapté aux motos japonaises, chinoises et indiennes courantes en Afrique. 15h de vidéos, checklist d''''entretien mensuel et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/074_mecanique-moto-et-entretien.pdf'),
('Réparation de Téléphones Portables', 'Réparez les smartphones : écran, batterie, connecteur.', 'Devenez technicien en réparation de smartphones : démontage sécurisé, remplacement d''''écran LCD et OLED, changement de batterie et connecteur de charge, reballing de puces BGA, récupération de données et réinstallation du firmware. 15h de vidéos, guide des pièces détachées en Afrique et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/075_reparation-de-telephones-portables.pdf'),
('Artisanat et Bijouterie Fantaisie', 'Créez des bijoux et accessoires à vendre.', 'Créez des bijoux et accessoires originaux à vendre en ligne et en boutique. Travail des perles, fils métalliques (cuivre, aluminium), résine UV, créations en wax et tissus africains. Montage, finitions, packaging créatif et tarification. 10h de vidéos, liste de fournisseurs africains et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/076_artisanat-et-bijouterie-fantaisie.pdf'),
('Cordonnerie et Réparation de Chaussures', 'Réparez semelles, coutures et teintures.', 'Maîtrisez les techniques de cordonnerie : recollage de semelles, réparation des coutures, remplacement des talons, teinture du cuir, imperméabilisation et restauration de chaussures de luxe. Outils spécialisés, colles et matériaux. 10h de vidéos pratiques et attestation RIVO.', 2000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/077_cordonnerie-et-reparation-de-chaussures.pdf'),
('Tapisserie et Ameublement', 'Restaurez et créez des meubles tapissés.', 'Restaurez et créez des canapés, fauteuils, têtes de lit et banquettes tapissés. Dépose de l''''ancienne tapisserie, remplacement de la mousse et des ressorts, choix des tissus (wax, velours, cuir synthétique), agrafage et finitions. 15h de vidéos en atelier et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/078_tapisserie-et-ameublement.pdf'),
('Peinture en Bâtiment et Décoration', 'Peignez comme un pro : murs, plafonds, boiseries.', 'Maîtrisez la peinture en bâtiment : préparation des surfaces (ragréage, ponçage, impression), application au rouleau et au pinceau, finitions (mat, satiné, brillant), effets décoratifs (patine, béton ciré, ardoise) et respect des temps de séchage. 10h de vidéos et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/079_peinture-en-batiment-et-decoration.pdf'),
('Carrelage et Revêtement de Sol', 'Posez du carrelage comme un professionnel.', 'Réalisez vos propres travaux de carrelage : mesure et calepinage, préparation du support, application de colle (mortier-colle et double encollage), découpe à la carrelette, poses spéciales (chevrons, hexagone, opus incertum), jointoiement et nettoyage. 15h de vidéos sur chantier et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/080_carrelage-et-revetement-de-sol.pdf'),
('Maçonnerie et Construction', 'Bases de la construction : fondations, murs, béton.', 'Apprenez les bases de la construction en Afrique : implantation, fondations superficielles, murs en parpaings, chaînages horizontaux et verticaux, béton armé (dosage, coffrage, ferraillage), enduits et normes locales. 20h de vidéos sur chantier réel, fiches techniques et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/081_maconnerie-et-construction.pdf'),
('Permis Poids Lourd et Transport', 'Préparez le permis poids lourd et la logistique transport.', 'Préparez votre permis poids lourd (catégorie C et CE) et maîtrisez les aspects professionnels du transport routier : code de la route PL, conduite spécifique, réglementation sociale (temps de conduite), tachygraphe, gestion d''''une flotte de véhicules. 20h de vidéos et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/082_permis-poids-lourd-et-transport.pdf'),
('Secourisme et Premiers Secours', 'Apprenez les gestes qui sauvent des vies.', 'Maîtrisez les gestes de premiers secours qui sauvent des vies : réanimation cardio-pulmonaire (RCP) adulte, enfant et nourrisson, utilisation du défibrillateur (DAE), position latérale de sécurité (PLS), gestion des étouffements, hémorragies et brûlures. 8h de vidéos, fiches mémo et attestation RIVO.', 2000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/083_secourisme-et-premiers-secours.pdf'),
('Incendie et Sécurité Incendie', 'Prévention et lutte contre les incendies.', 'Formation complète à la prévention et la lutte contre les incendies en entreprise et dans les bâtiments. Types d''''extincteurs et leur utilisation, plans d''''évacuation, rôle du serre-file et guide-file, alarmes incendie, normes de sécurité et exercices d''''évacuation. 10h de vidéos et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/084_incendie-et-securite-incendie.pdf'),
('Surveillance et Vidéoprotection', 'Installez des systèmes de caméras et alarmes.', 'Installez et configurez des systèmes de vidéoprotection et d''''alarme anti-intrusion. Caméras IP (ONVIF), NVR/DVR, câblage Cat6 et coaxial, accès à distance via smartphone, contrôle d''''accès RFID et maintenance. 12h de vidéos, guide des marques disponibles en Afrique et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/085_surveillance-et-videoprotection.pdf'),
('Domotique et Maison Intelligente', 'Automatisez votre maison : lumières, volets, alarmes.', 'Transformez votre maison en maison connectée : automatisation des lumières, volets roulants, climatisation, alarmes et prises connectées. Protocoles Zigbee et WiFi, box domotique Jeedom/Home Assistant, assistants vocaux. 15h de vidéos, kits pratiques recommandés et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/086_domotique-et-maison-intelligente.pdf'),
('Robotique et Arduino', 'Construisez et programmez des robots simples.', 'Découvrez la robotique et l''''électronique avec Arduino (C++). Capteurs (ultrason, IR, DHT22), moteurs DC et pas à pas, servomoteurs, afficheurs LCD, modules WiFi ESP8266. Projets progressifs : robot suiveur de ligne, bras robotique, station météo. 20h de vidéos, guide des kits en Afrique et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/087_robotique-et-arduino.pdf'),
('Impression 3D et Modélisation', 'Imprimez vos créations en 3D.', 'Maîtrisez l''''impression 3D FDM : logiciels de tranchage (Cura, PrusaSlicer), paramètres d''''impression (couches, remplissage, supports), matériaux (PLA, PETG, TPU, ABS), calibration, détection et correction des problèmes d''''impression. 10h de vidéos, bibliothèque de fichiers STL prêts à imprimer et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/088_impression-3d-et-modelisation.pdf'),
('Commerce International et Import-Export', 'Importez et exportez des marchandises en Afrique.', 'Maîtrisez le commerce international : procédures douanières africaines (OHADA), documents de transport (connaissement, LTA, CMR), incoterms 2020, modes de paiement (crédit documentaire, remise documentaire, SWIFT), assurance transport et gestion des litiges. 15h de vidéos et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/089_commerce-international-et-import-export.pdf'),
('Gestion des Ressources Humaines', 'Gérez le personnel : recrutement, paie, droit social.', 'Maîtrisez la gestion des ressources humaines adaptée au contexte africain : processus de recrutement, rédaction de contrats de travail (OHADA), gestion de la paie, droit du travail, évaluation des performances, gestion des conflits et plan de formation. 20h de vidéos, modèles de documents RH et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/090_gestion-des-ressources-humaines.pdf'),
('Comptabilité Générale et Fiscalité', 'Tenez la comptabilité d''''une entreprise.', 'Maîtrisez la comptabilité générale selon le plan SYSCOHADA révisé : saisie des pièces comptables, journaux (achats, ventes, banque, caisse), grand livre, balance et états financiers (bilan, compte de résultat). TVA, IS et déclarations fiscales. 25h de vidéos, 50 exercices avec corrigés et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/091_comptabilite-generale-et-fiscalite.pdf'),
('Gestion de la Paie', 'Calculez et gérez les salaires de vos employés.', 'Maîtrisez le calcul et l''''édition des bulletins de salaire : salaire brut, cotisations sociales (CNPS/ONSS/INPS), IRPP, salaire net, congés payés, heures supplémentaires et déclarations sociales. Logiciel de paie et modèles Excel. 15h de vidéos, modèles de bulletins par pays africain et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/092_gestion-de-la-paie.pdf'),
('Assistanat de Direction et Secrétariat', 'Devenez assistant(e) de direction efficace.', 'Formation complète en assistanat de direction : gestion d''''agenda et organisation de réunions, rédaction professionnelle (notes, comptes-rendus, rapports), gestion du courrier, accueil téléphonique, organisation de voyages d''''affaires et maîtrise des logiciels bureautiques. 15h de vidéos, templates et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/093_assistanat-de-direction-et-secretariat.pdf'),
('Télémarketing et Vente par Téléphone', 'Vendez par téléphone avec des scripts qui marchent.', 'Devenez expert en vente téléphonique : accroche téléphonique en moins de 10 secondes, qualification du prospect, argumentaire structuré, gestion des objections par téléphone (trop cher, pas intéressé, je rappelle), conclusion et relance. 8h de vidéos, scripts audio enregistrés et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/094_telemarketing-et-vente-par-telephone.pdf'),
('Événementiel et Organisation de Fêtes', 'Organisez des événements réussis : mariages, anniversaires.', 'Maîtrisez l''''organisation d''''événements de A à Z : mariages, anniversaires, conférences et événements corporate. Budget prévisionnel, sélection et coordination des prestataires (traiteur, DJ, photographe, décorateur), planning Gantt, jour J et bilan. 15h de vidéos, checklists événementielles et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/095_evenementiel-et-organisation-de-fetes.pdf'),
('Journalisme et Reportage', 'Devenez journaliste ou reporter.', 'Formation complète au journalisme : techniques d''''enquête et de vérification des sources, interview professionnelle, rédaction journalistique (pyramide inversée), éthique de la presse, tournage de reportage vidéo et montage. 15h de vidéos, exercices terrain et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/096_journalisme-et-reportage.pdf'),
('Blogging et Création de Site d''''Actualité', 'Lancez votre blog ou site d''''info rentable.', 'Créez un blog ou site d''''information rentable : choisir sa niche, créer son site WordPress, rédiger des articles SEO, développer son audience, monétiser (Google AdSense, articles sponsorisés, abonnements) et respecter les règles juridiques de la presse en ligne. 12h de vidéos et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/097_blogging-et-creation-de-site-dactualite.pdf'),
('Streaming et Gaming sur Twitch', 'Devenez streamer et gagnez de l''''argent en jouant.', 'Lancez votre carrière de streamer sur Twitch et YouTube Gaming : configuration OBS Studio, overlay et alerts personnalisés, interaction avec la communauté en direct, croissance de la chaîne et monétisation (subscriptions, bits, sponsors). 10h de vidéos, assets de streaming offerts et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/098_streaming-et-gaming-sur-twitch.pdf'),
('Langue Espagnole Débutant', 'Apprenez l''''espagnol pour voyager et travailler.', 'Apprenez l''''espagnol de zéro : alphabet et prononciation, vocabulaire du quotidien et des affaires, grammaire de base (présent, passé, futur), conversation pour voyager et situations professionnelles. Méthode immersive et progressive. 20h de vidéos, exercices audio, fiches mémo et attestation RIVO.', 3500, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/099_langue-espagnole-debutant.pdf'),
('Langue Allemande Débutant', 'Initiez-vous à l''''allemand pour les affaires.', 'Découvrez l''''allemand avec une méthode progressive et pratique : prononciation des sons allemands, articles (der/die/das), vocabulaire essentiel, situations quotidiennes et business. Idéal pour ceux qui souhaitent étudier ou travailler en Allemagne ou Suisse. 20h de vidéos, exercices audio et attestation RIVO.', 3500, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/100_langue-allemande-debutant.pdf'),
('Langue Chinoise Mandarin Débutant', 'Découvrez le mandarin pour le commerce avec la Chine.', 'Apprenez le mandarin pour mieux commercer avec la Chine. Système pinyin, tons, caractères de base (50 caractères essentiels), salutations, chiffres, négociation commerciale simple et communication avec fournisseurs chinois. 20h de vidéos, fiches audio et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/101_langue-chinoise-mandarin-debutant.pdf'),
('Langue Arabe Débutant', 'Apprenez l''''arabe pour les affaires et les voyages.', 'Apprenez l''''arabe standard (littéral) pour vos affaires et voyages au Maghreb et au Moyen-Orient. Alphabet arabe, prononciation, vocabulaire du quotidien et commercial, phrases de base pour voyager et négocier. 20h de vidéos progressives, exercices audio et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/102_langue-arabe-debutant.pdf'),
('Français des Affaires et Rédaction Pro', 'Perfectionnez votre français écrit et oral.', 'Perfectionnez votre maîtrise du français professionnel : orthographe avancée, syntaxe, rédaction de rapports et comptes-rendus, présentations orales, discours formels, correspondance professionnelle et écriture administrative. 15h de vidéos, 100 exercices corrigés et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/103_francais-des-affaires-et-redaction-pro.pdf'),
('Prise de Parole en Public', 'Parlez avec aisance devant un auditoire.', 'Surmontez votre peur de parler en public et développez votre charisme. Gestion du trac et de l''''anxiété, travail de la voix (diction, débit, intonation), gestuelle et langage corporel, structure du discours et storytelling. Exercices filmés avec auto-analyse. 10h de vidéos et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/104_prise-de-parole-en-public.pdf'),
('Négociation Commerciale', 'Obtenez les meilleurs accords dans vos négociations.', 'Devenez un négociateur expert : préparation stratégique (BATNA, objectifs), tactiques de négociation (ancrage, silence, faux pivot), gestion des émotions, concessions calculées, closing et rédaction d''''accords. Adapté aux négociations commerciales africaines. 10h de vidéos, scripts et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/105_negociation-commerciale.pdf'),
('Gestion du Temps et Productivité', 'Faites plus en moins de temps et sans stress.', 'Doublez votre productivité avec des méthodes éprouvées : GTD (Getting Things Done), technique Pomodoro, matrice d''''Eisenhower, planification hebdomadaire, gestion de la procrastination et outils numériques (Notion, Todoist, Google Calendar). 8h de vidéos, templates de planification et attestation RIVO.', 2000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/106_gestion-du-temps-et-productivite.pdf'),
('Leadership et Management d''''Équipe', 'Devenez un leader inspirant et efficace.', 'Développez vos compétences de leader et de manager : styles de leadership adaptés au contexte africain, motivation et engagement de l''''équipe, délégation efficace, feedback constructif, résolution de conflits et conduite du changement. Études de cas de leaders africains. 15h de vidéos et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/107_leadership-et-management-dequipe.pdf'),
('Animation et Travail avec les Enfants', 'Devenez animateur périscolaire ou de colonie.', 'Formez-vous à l''''animation périscolaire et extrascolaire : techniques d''''animation de groupe, jeux coopératifs et créatifs, gestion des comportements difficiles, sécurité des enfants, activités adaptées par tranches d''''âge et premiers secours pédiatriques. 10h de vidéos, guide de 50 activités avec matériel local et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/108_animation-et-travail-avec-les-enfants.pdf'),
('Pêche et Aquaculture', 'Techniques modernes de pêche et élevage de poissons.', 'Modernisez vos techniques de pêche et développez une activité aquacole rentable. Pêche artisanale améliorée, cages flottantes en eaux douces et lacustres, étangs piscicoles en terre, alimentation artificielle, prévention des maladies et commercialisation. 15h de vidéos terrain en Afrique et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/109_peche-et-aquaculture.pdf'),
('Aviculture et Élevage de Poulets', 'Élevage de poulets de chair et pondeuses rentable.', 'Lancez ou améliorez votre élevage avicole : construction du poulailler (dimensions, ventilation, litière), choix des races (Cobb 500, Ross 308 pour chair ; ISA Brown pour pondeuses), alimentation, programme de vaccination, prévention de la maladie de Newcastle et commercialisation. 15h de vidéos et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/110_aviculture-et-elevage-de-poulets.pdf'),
('Élevage d''''Escargots Géants Africains', 'L''''escargot, un business lucratif et méconnu.', 'L''''héliciculture africaine (élevage d''''Achatina fulica et Achatina achatina) : construction de l''''enclos, substrat adapté, alimentation (feuilles, son, coquilles d''''œufs), reproduction contrôlée, lutte contre les parasites, récolte et commercialisation aux restaurants et à l''''export. Très rentable et peu coûteux. Attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/111_elevage-descargots-geants-africains.pdf'),
('Maraîchage et Culture de Légumes', 'Cultivez tomates, piments, salades et gombos.', 'Maîtrisez la culture maraîchère en Afrique subsaharienne : préparation du sol, semis et repiquage, techniques d''''irrigation (goutte-à-goutte), fertilisation organique et minérale, protection phytosanitaire (ravageurs et maladies), récolte et conservation. Fiches techniques par légume (tomate, piment, oignon, carotte). Attestation RIVO.', 3500, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/112_maraichage-et-culture-de-legumes.pdf'),
('Transformation Agroalimentaire', 'Transformez vos récoltes en produits à valeur ajoutée.', 'Créez des produits agroalimentaires à forte valeur ajoutée à partir de vos récoltes : jus de fruits (baobab, ditax, tamarin, bouye), confitures, légumes séchés, huile de palme artisanale, farine de manioc, gari et conserves. Hygiène alimentaire (HACCP simplifié), emballage et réglementation. Attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/113_transformation-agroalimentaire.pdf'),
('Pisciculture et Élevage de Tilapia', 'Produisez du poisson en bassin ou étang.', 'Produisez du tilapia (Oreochromis niloticus) et du catfish (Clarias gariepinus) en bassin en béton ou en étang en terre. Qualité et gestion de l''''eau (pH, oxygène, température), alevinage et grossissement, alimentation artificielle, prévention des maladies, récolte et vente. Calendrier de production et attestation RIVO.', 4500, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/114_pisciculture-et-elevage-de-tilapia.pdf'),
('Gestion de l''''Eau et Irrigation', 'Maîtrisez l''''irrigation pour vos cultures.', 'Optimisez l''''utilisation de l''''eau pour vos cultures : irrigation goutte-à-goutte (drip), aspersion, gravitaire et sub-surface. Pompes solaires, forages artisanaux, bassins de stockage, calcul des besoins en eau par culture et installation complète. Schémas d''''installation, calcul des coûts et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/115_gestion-de-leau-et-irrigation.pdf'),
('Permaculture et Agriculture Durable', 'Cultivez en respectant la nature et le sol.', 'Adoptez les principes de la permaculture pour une agriculture productive et durable : design permaculturel, compostage et lombricompostage, associations de cultures bénéfiques, buttes jardinières, agroforesterie et conservation de la biodiversité. Plans de jardin téléchargeables et attestation RIVO.', 3500, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/116_permaculture-et-agriculture-durable.pdf'),
('Nutrition et Diététique', 'Mangez sainement et équilibrez votre alimentation.', 'Apprenez les bases de la nutrition et de la diététique adaptées aux réalités africaines. Groupes d''''aliments et leurs rôles, macronutriments (protéines, glucides, lipides), micronutriments (vitamines, minéraux), menus équilibrés à base d''''aliments locaux, gestion du poids et alimentation du sportif. 12h de vidéos et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/117_nutrition-et-dietetique.pdf'),
('Cuisine Africaine Traditionnelle', 'Maîtrisez les grands classiques de la cuisine africaine.', 'Apprenez à cuisiner les plats emblématiques de l''''Afrique de l''''Ouest et du Centre : attiéké poisson, alloco braisé, mafé de mouton, yassa poulet sénégalais, ndolé camerounais, thiéboudiène, sauce graine, arachide et poulet braisé façon maquis. 50 recettes détaillées avec photos étape par étape et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/118_cuisine-africaine-traditionnelle.pdf'),
('Boulangerie et Viennoiserie', 'Faites votre pain, croissants et brioches maison.', 'Maîtrisez les techniques de boulangerie et viennoiserie adaptées aux fours disponibles en Afrique. Pain de mie, baguette, pain complet, croissants feuilletés, brioches, pains spéciaux (sésame, olive, noix). Pétrissage, levée, façonnage et cuisson. 30 recettes détaillées et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/119_boulangerie-et-viennoiserie.pdf'),
('Chocolaterie et Confiserie', 'Fabriquez des chocolats et bonbons à vendre.', 'Créez des chocolats artisanaux et confiseries à vendre : tempérage du chocolat noir, au lait et blanc, moulage en tablettes et pralinés, ganaches parfumées, truffes, caramels, nougats et pâtes de fruits. Valorisez le cacao africain. Emballage et conditionnement professionnel. 10h de vidéos et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/120_chocolaterie-et-confiserie.pdf'),
('Mixologie et Art du Cocktail', 'Devenez barman et créez des cocktails originaux.', 'Maîtrisez l''''art de la mixologie : matériel du barman (shaker, jigger, muddle, passoire), techniques (shake, stir, float, muddle), cocktails classiques internationaux (Mojito, Daiquiri, Margarita) et créations africaines à base de fruits locaux (baobab, gingembre, bissap). 8h de vidéos et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/121_mixologie-et-art-du-cocktail.pdf'),
('Coaching Sportif et Fitness', 'Devenez coach sportif certifié.', 'Formez-vous au coaching sportif et fitness : anatomie et physiologie de l''''exercice, conception de programmes d''''entraînement personnalisés (musculation, cardio, HIIT, mobilité), nutrition sportive, coaching individuel et en groupe, gestion d''''un coaching à distance. 20h de vidéos, fiches d''''exercices et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/122_coaching-sportif-et-fitness.pdf'),
('Football : Techniques et Tactiques', 'Améliorez votre jeu et comprenez les tactiques.', 'Élevez votre niveau de football : techniques individuelles (contrôle orienté, dribbles, passes longues, tirs de puissance et de précision, jeu de tête), positionnement tactique, systèmes de jeu (4-3-3, 4-4-2, 4-2-3-1), phases de set-pièces et préparation physique. 15h de vidéos terrain et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/123_football-techniques-et-tactiques.pdf'),
('Natation pour Débutants', 'Apprenez à nager quel que soit votre âge.', 'Apprenez à nager de zéro à l''''aise dans l''''eau : gestion de la respiration, flottaison, brasse coulée, crawl, dos crawlé et départ plongé. Conseils de sécurité aquatique, nage en mer et en rivière. Vidéos en piscine claires et progressives, adaptées pour les adultes et les enfants. Attestation RIVO.', 2000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/124_natation-pour-debutants.pdf'),
('Arts Martiaux et Self-Défense', 'Apprenez à vous défendre en toute situation.', 'Maîtrisez les techniques de self-défense essentielles : positions de garde, esquives et blocages, frappes efficaces (poing, coude, genou, pied), clés de bras, projections et sorties de prises. Inspiré du karaté, judo, boxe et krav maga. Démonstrations filmées en haute qualité. 15h de vidéos et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/125_arts-martiaux-et-self-defense.pdf'),
('Guitare Acoustique pour Débutants', 'Jouez vos premières chansons à la guitare.', 'Apprenez la guitare acoustique de zéro sans connaissances musicales préalables. Accords de base (Do, Ré, Mi, Fa, Sol, La, Si), transitions fluides, rythmes (strumming et fingerpicking), arpèges, gammes pentatoniques et chansons africaines et internationales complètes. 15h de vidéos, tablatures et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/126_guitare-acoustique-pour-debutants.pdf'),
('Piano et Clavier Débutant', 'Apprenez le piano même sans solfège.', 'Découvrez le piano et le clavier électronique sans passer par des années de solfège. Méthode visuelle : notes sur le clavier, accords majeurs et mineurs, gammes, rythmes courants, accompagnement de chansons populaires et morceaux africains. 15h de vidéos progressives, partitions simplifiées et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/127_piano-et-clavier-debutant.pdf'),
('Chant et Technique Vocale', 'Améliorez votre voix et chantez juste.', 'Développez votre voix et chantez avec confiance et justesse. Respiration diaphragmatique, placement de la voix, travail de la justesse, extension du registre vocal, puissance et interprétation émotionnelle. Exercices audio quotidiens progressifs. 10h de vidéos, enregistrements de référence et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/128_chant-et-technique-vocale.pdf'),
('Danse Moderne et Chorégraphie', 'Apprenez à danser : afro, coupé-décalé, ndombolo.', 'Maîtrisez les danses africaines tendance : afrobeats, coupé-décalé ivoirien, ndombolo congolais, amapiano sud-africain et azonto ghanéen. Pas de base, coordination des mouvements, créativité, enchaînements et création de chorégraphies pour scène et réseaux sociaux. 10h de vidéos et attestation RIVO.', 2000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/129_danse-moderne-et-choregraphie.pdf'),
('DJing et Mixage pour Débutants', 'Devenez DJ : platines, transitions, sets.', 'Lancez votre carrière de DJ : matériel (contrôleur DJ, platines, table de mixage), logiciels (Serato DJ, Rekordbox), beatmatching précis, transitions fluides, EQ et effets, mix harmonique (Camelot), construction d''''un set et promotion. 10h de vidéos, samples et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/130_djing-et-mixage-pour-debutants.pdf'),
('Scénario et Écriture de Film', 'Écrivez votre premier scénario de court-métrage.', 'Écrivez votre premier scénario de court ou long métrage. Structure en 3 actes (setup, confrontation, résolution), création de personnages complexes, dialogues naturels et percutants, mise en page professionnelle (logiciel Celtx gratuit) et analyse de scénarios africains à succès. 12h de vidéos, templates et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/131_scenario-et-ecriture-de-film.pdf'),
('Réalisation de Court-Métrage', 'Réalisez votre premier film de A à Z.', 'Réalisez votre premier court-métrage professionnel de A à Z : développement du scénario, casting et direction d''''acteurs, repérages, tournage (cadre, lumière naturelle et artificielle, son), montage, étalonnage et diffusion sur festivals africains et plateformes en ligne. 20h de vidéos et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/132_realisation-de-court-metrage.pdf'),
('Animation 2D avec Adobe Animate', 'Créez des dessins animés et animations web.', 'Créez des dessins animés et animations web interactives avec Adobe Animate. Images clés, interpolations (mouvement, forme, couleur), personnages riggés, symboles et bibliothèque, export vidéo et HTML5 Canvas. Projets : générique animé, pub animée et court-métrage 2D. 15h de vidéos et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/133_animation-2d-avec-adobe-animate.pdf'),
('Effets Spéciaux VFX pour le Cinéma', 'Ajoutez des effets numériques à vos vidéos.', 'Créez des effets visuels époustouflants avec After Effects et Nuke. Incrustation écran vert (chroma key), tracking et compositing, systèmes de particules, explosions VFX, ajout d''''éléments 3D dans des séquences réelles et titres cinéma. Assets VFX premium inclus. 20h de vidéos et attestation RIVO.', 10000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/134_effets-speciaux-vfx-pour-le-cinema.pdf'),
('Acting et Jeu d''''Acteur', 'Devenez acteur pour le cinéma et le théâtre.', 'Développez vos talents d''''acteur pour le cinéma africain, la télévision et le théâtre. Travail de l''''improvisation, exploration émotionnelle, mémorisation et incarnation de texte, direction par le réalisateur, jeu face caméra et préparation aux castings. Exercices filmés et analyse. 15h de vidéos et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/135_acting-et-jeu-dacteur.pdf'),
('Voix Off et Doublage', 'Devenez doubleur ou narrateur professionnel.', 'Lancez votre carrière de comédien de voix off et de doublage. Techniques de respiration et d''''articulation, jeu vocal (émotions, personnages), synchronisation labiale pour le doublage, création d''''un home studio économique, constitution de son book audio et démarchage de clients. 10h de vidéos et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/136_voix-off-et-doublage.pdf'),
('Son et Ingénierie Audio', 'Maîtrisez la prise de son et le mixage audio.', 'Maîtrisez l''''ingénierie du son de A à Z : types de microphones (dynamique, condensateur, ruban), placement et acoustique, table de mixage analogique et numérique, DAW (Reaper, Pro Tools), plugins (compression, EQ, réverbération), mixage professionnel et mastering. 15h de vidéos et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/137_son-et-ingenierie-audio.pdf'),
('Éclairage et Light Design', 'Maîtrisez l''''éclairage pour la photo, vidéo et scène.', 'Maîtrisez l''''éclairage pour la photographie (studio, reportage), la vidéo (interview, fiction), la scène (concerts, théâtre) et l''''événementiel. Sources lumineuses (LED, tungstène, flash), placement (clé, remplissage, contre-jour), diffuseurs, protocole DMX et régie lumière. 12h de vidéos et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/138_eclairage-et-light-design.pdf'),
('Droit des Affaires OHADA', 'Comprenez le droit des affaires en Afrique.', 'Maîtrisez le droit des affaires OHADA applicable dans 17 pays africains. Acte Uniforme sur les Sociétés Commerciales (SARL, SA), droit commercial général, sûretés et garanties, procédures d''''exécution et voies de recours, arbitrage CCJA et protection de la propriété intellectuelle. 20h de vidéos, modèles de contrats et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/139_droit-des-affaires-ohada.pdf'),
('Propriété Intellectuelle et Brevets', 'Protégez vos créations et inventions.', 'Protégez efficacement vos créations intellectuelles en Afrique : droits d''''auteur (copyright), marques déposées, brevets d''''invention, dessins et modèles industriels, indications géographiques. Procédures d''''enregistrement auprès de l''''OAPI et de l''''ARIPO. Guides pratiques et formulaires de dépôt inclus. Attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/140_propriete-intellectuelle-et-brevets.pdf'),
('Géopolitique et Relations Internationales', 'Comprenez les enjeux mondiaux et africains.', 'Analysez les grands enjeux géopolitiques contemporains avec un focus africain. Histoire des relations internationales, conflits armés en cours, compétitions des grandes puissances en Afrique, organisations régionales (UA, CEDEAO, SADC), diplomatie et commerce international. 15h de vidéos, analyses et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/141_geopolitique-et-relations-internationales.pdf'),
('Histoire de l''''Afrique et des Civilisations', 'Connaissez la vraie histoire du continent africain.', 'Redécouvrez l''''histoire complète et non déformée du continent africain. Grandes civilisations (Égypte ancienne, Nubie, Koush), empires médiévaux (Mali, Ghana, Songhaï, Kongo, Zimbabwe), traite négrière, colonisation, résistances, décolonisation et renaissance africaine contemporaine. 15h de vidéos, cartes historiques et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/142_histoire-de-lafrique-et-des-civilisations.pdf'),
('Grandes Pensées Philosophiques', 'Découvrez les grands philosophes et leurs idées.', 'Voyage à travers les grandes pensées qui ont façonné le monde. Philosophie grecque (Socrate, Platon, Aristote), philosophie des Lumières (Descartes, Kant, Rousseau), philosophie moderne (Nietzsche, Sartre, Camus) et philosophie africaine (Ubuntu, Cheikh Anta Diop, Frantz Fanon). 12h de vidéos, résumés et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/143_grandes-pensees-philosophiques.pdf'),
('Art Oratoire et Éloquence', 'Devenez un orateur captivant et persuasif.', 'Développez votre art oratoire et votre éloquence pour captiver n''''importe quel auditoire. Rhétorique classique (ethos, pathos, logos), figures de style (métaphore, anaphore, chiasme), construction d''''un discours percutant, concours d''''éloquence et prise de parole spontanée. Exercices filmés et analyse. 10h de vidéos et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/144_art-oratoire-et-eloquence.pdf'),
('Calligraphie et Belle Écriture', 'Apprenez l''''art de la belle écriture manuscrite.', 'Maîtrisez l''''art de la calligraphie et de la belle écriture. Styles : moderne (brush lettering), Copperplate (plume oblique), gothique et calligraphie arabe. Matériel (plumes, pinceaux, encres), exercices progressifs sur les lettres, mots et compositions artistiques. 8h de vidéos et attestation RIVO.', 2000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/145_calligraphie-et-belle-ecriture.pdf'),
('Poterie et Céramique', 'Créez des objets en argile : pots, vases, sculptures.', 'Apprenez l''''art de la poterie et de la céramique : montage à la main (colombins, motte), tournage sur tour de potier, modelage de sculptures, émaillage, cuisson au four et techniques africaines traditionnelles. Création de vaisselle, vases et objets décoratifs à vendre. 12h de vidéos en atelier et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/146_poterie-et-ceramique.pdf'),
('Vannerie et Tissage Artisanal', 'Fabriquez paniers, sacs et objets en fibres végétales.', 'Maîtrisez les techniques de vannerie et de tissage avec des fibres végétales africaines (raphia, rotin, paille, lianes). Tressage en spirale, en natte et en twill, teintures naturelles, motifs géométriques traditionnels et créations contemporaines. 10h de vidéos, liste de matières premières locales et attestation RIVO.', 2000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/147_vannerie-et-tissage-artisanal.pdf'),
('Reliure et Restauration de Livres', 'Réparez et restaurez des livres anciens et modernes.', 'Apprenez l''''art de la reliure : couture à la main (points de reliure), encoller et assembler les cahiers, fabrication de la couverture (carton, cuir, tissu), dorure à la feuille d''''or et restauration de livres anciens endommagés. Guide complet du matériel et des fournisseurs. 10h de vidéos et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/148_reliure-et-restauration-de-livres.pdf'),
('Horlogerie et Réparation de Montres', 'Réparez montres mécaniques et à quartz.', 'Devenez horloger : démontage et nettoyage d''''un mouvement mécanique, remplacement des rouages et pivots, réglage du spiral et du balancier, révision complète d''''une montre à quartz et remplacement de pile. Outils spécialisés, loupe et tour d''''établi. 15h de vidéos, guide d''''achat d''''outils et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/149_horlogerie-et-reparation-de-montres.pdf'),
('Lutherie et Fabrication de Guitare', 'Fabriquez votre propre guitare acoustique.', 'Fabriquez votre guitare acoustique de A à Z : sélection et séchage des bois (épicéa, acajou, palissandre), découpe de la table d''''harmonie et du fond, assemblage de la caisse, fabrication du manche et de la touche, vernissage Nitrocellulose et montage mécanique. 25h de vidéos en atelier de lutherie et attestation RIVO.', 9000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/150_lutherie-et-fabrication-de-guitare.pdf'),
('Taxidermie et Conservation Animale', 'Apprenez à naturaliser les animaux pour musées.', 'Maîtrisez les techniques de taxidermie pour naturaliser les animaux destinés aux musées, collections scientifiques et trophées de chasse légaux. Préparation et tannage de la peau, modélisation du mannequin, montage et finitions. Législation africaine sur la faune sauvage protégée. 15h de vidéos et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/151_taxidermie-et-conservation-animale.pdf'),
('Cartographie et SIG', 'Créez des cartes avec les Systèmes d''''Information Géographique.', 'Maîtrisez la cartographie numérique avec QGIS (gratuit). Import de données spatiales (shapefiles, GeoJSON, rasters), géoréférencement, analyses géospatiales, création de cartes thématiques professionnelles et export. Données géographiques africaines libres incluses. 15h de vidéos, exercices pratiques et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/152_cartographie-et-sig.pdf'),
('Topographie et Relevés de Terrain', 'Mesurez et cartographiez des terrains.', 'Maîtrisez les techniques topographiques pour l''''arpentage et le relevé de terrains. Utilisation du théodolite, du niveau de chantier et du GPS RTK. Calcul de surfaces et volumes, report de plans, implantation de bâtiments et routes. 15h de vidéos avec exercices terrain en Afrique et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/153_topographie-et-releves-de-terrain.pdf'),
('Géologie et Recherche Minière', 'Comprenez les sols, roches et ressources minières.', 'Explorez la géologie africaine et les techniques de prospection minière artisanale légale. Minéralogie (identification des roches et minéraux), cartes géologiques, méthodes de prospection (géophysique, géochimie), exploitation artisanale de l''''or, des diamants et autres minerais. 20h de vidéos et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/154_geologie-et-recherche-miniere.pdf'),
('Météorologie et Climatologie', 'Comprenez et prédisez le temps qu''''il fait.', 'Comprenez les phénomènes météorologiques et climatiques qui impactent l''''Afrique. Formation et types de nuages, systèmes de pression atmosphérique, vents (harmattan, mousson), instruments météo, lecture de cartes synoptiques et prévisions pour l''''agriculture. 10h de vidéos, données météo africaines et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/155_meteorologie-et-climatologie.pdf'),
('Océanographie et Environnement Marin', 'Étudiez les océans et la vie marine.', 'Découvrez les océans qui bordent l''''Afrique (Atlantique, Indien). Courants marins (ITCZ, Benguela), marées, écosystèmes côtiers africains (mangroves, récifs coralliens), ressources halieutiques, pollution plastique et actions de conservation. 12h de vidéos, documentaires et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/156_oceanographie-et-environnement-marin.pdf'),
('Zoologie et Comportement Animal', 'Étudiez les animaux sauvages et domestiques.', 'Étudiez la faune africaine dans sa richesse et sa diversité. Classification zoologique, éthologie (comportements de reproduction, alimentation, communication), conservation des espèces menacées, safaris responsables et cohabitation homme-faune. Documentaires animaliers HD et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/157_zoologie-et-comportement-animal.pdf'),
('Botanique et Étude des Plantes', 'Identifiez et étudiez les plantes d''''Afrique.', 'Apprenez à identifier et étudier la flore africaine. Classification botanique (familles, genres, espèces), morphologie végétale, usages médicinaux et alimentaires des plantes locales, technique d''''herbier et notions de conservation des écosystèmes végétaux. 100 fiches d''''identification de plantes africaines illustrées et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/158_botanique-et-etude-des-plantes.pdf'),
('Astronomie et Observation du Ciel', 'Observez les étoiles, planètes et galaxies.', 'Découvrez l''''astronomie depuis l''''Afrique, bénéficiant d''''un ciel nocturne exceptionnel. Télescope et jumelles (choisir et utiliser), cartes du ciel et logiciels (Stellarium gratuit), constellations africaines et leur signification culturelle, planètes du système solaire et astrophotographie avec smartphone. 10h de vidéos et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/159_astronomie-et-observation-du-ciel.pdf'),
('Mathématiques Appliquées', 'Renforcez vos bases en maths pour les études et le travail.', 'Renforcez solidement vos bases mathématiques pour réussir vos études, vos concours et votre vie professionnelle. Algèbre (équations, systèmes, polynômes), géométrie (plan et espace), statistiques et probabilités, suites et fonctions. 200 exercices progressifs avec corrigés détaillés et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/160_mathematiques-appliquees.pdf'),
('Physique et Chimie Générale', 'Comprenez les bases de la physique et de la chimie.', 'Maîtrisez les fondamentaux de la physique et de la chimie. Mécanique (forces, énergie, mouvements), thermodynamique, électricité (circuits, lois de Kirchhoff), optique, structure de l''''atome, réactions chimiques et stoechiométrie. Expériences pratiques filmées, exercices et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/161_physique-et-chimie-generale.pdf'),
('Biologie et Sciences de la Vie', 'Étudiez le vivant : cellules, génétique, évolution.', 'Explorez les sciences du vivant : biologie cellulaire (cellule eucaryote et procaryote), génétique et hérédité (ADN, ARN, mutations), physiologie humaine (systèmes nerveux, cardiovasculaire, digestif), microbiologie et évolution des espèces. Schémas détaillés, animations 3D et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/162_biologie-et-sciences-de-la-vie.pdf'),
('Architecture et Conception de Bâtiments', 'Apprenez à concevoir des plans de maisons et bâtiments.', 'Apprenez à concevoir des plans architecturaux. Processus de conception (esquisse, avant-projet, projet), dessin technique à la main et avec AutoCAD/SketchUp, choix des matériaux locaux, normes parasismiques, bioclimatisme en contexte africain et lecture de plans de construction. 25h de vidéos et attestation RIVO.', 9000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/163_architecture-et-conception-de-batiments.pdf'),
('Urbanisme et Aménagement du Territoire', 'Concevez des villes et quartiers durables.', 'Comprenez et pratiquez l''''urbanisme africain : planification urbaine et territoriale, zonage et règlements d''''urbanisme, mobilité durable, gestion des espaces publics, accès à l''''eau et à l''''assainissement, participation citoyenne et smart city en Afrique. Études de cas de villes africaines exemplaires. 15h de vidéos et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/164_urbanisme-et-amenagement-du-territoire.pdf'),
('Génie Civil et Construction', 'Bases du génie civil : béton armé, structures, routes.', 'Maîtrisez les bases du génie civil africain : matériaux de construction (béton, acier, bois), calcul de structures simples, béton armé (dimensionnement, ferraillage), construction de routes et voiries, ouvrages hydrauliques et contrôle qualité sur chantier. 25h de vidéos, exercices et attestation RIVO.', 9000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/165_genie-civil-et-construction.pdf'),
('Énergies Renouvelables', 'Solaire, éolien, biomasse, hydraulique.', 'Maîtrisez les technologies des énergies renouvelables adaptées à l''''Afrique. Photovoltaïque (dimensionnement et installation), éolienne (petit éolien), biogaz (digesteur familial et communautaire), micro-hydraulique et gestion de mini-réseaux hybrides. 20h de vidéos, études de cas africains et attestation RIVO.', 8000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/166_energies-renouvelables.pdf'),
('Gestion de l''''Environnement et Déchets', 'Recyclage, traitement des déchets, économie circulaire.', 'Formation à la gestion durable des déchets et à l''''économie circulaire en contexte africain. Tri et collecte sélective, recyclage (plastique, papier, verre, métal), compostage communautaire, valorisation énergétique (biogaz), sensibilisation et projets de gestion des déchets. 12h de vidéos et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/167_gestion-de-lenvironnement-et-dechets.pdf'),
('Changement Climatique et Adaptation', 'Comprenez le climat et comment s''''adapter.', 'Comprendre le changement climatique et ses impacts spécifiques sur l''''Afrique. Mécanismes du réchauffement (gaz à effet de serre, rétroactions), impacts en Afrique (sécheresse, inondations, désertification), stratégies d''''adaptation (agriculture, eau, côtes) et négociations climatiques (COP). 10h de vidéos et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/168_changement-climatique-et-adaptation.pdf'),
('Diplomatie et Protocole', 'Maîtrisez les codes de la diplomatie internationale.', 'Maîtrisez les règles de la diplomatie et du protocole officiel. Cérémonial d''''État (accueil de chefs d''''État, préséances officielles), rédaction de notes verbales et diplomatiques, organisation de réceptions officielles, immunités diplomatiques et négociations bilatérales. Guide du protocole africain et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/169_diplomatie-et-protocole.pdf'),
('Archivistique et Gestion Documentaire', 'Classez et conservez les documents importants.', 'Maîtrisez la gestion professionnelle des archives physiques et numériques. Classification et indexation des documents, plan de classement, durée légale de conservation, numérisation et archivage électronique (GED), recherche rapide et destruction sécurisée. Logiciels libres de GED et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/170_archivistique-et-gestion-documentaire.pdf'),
('Bibliothéconomie et Gestion de Bibliothèque', 'Gérez une bibliothèque physique ou numérique.', 'Gérez efficacement une bibliothèque scolaire, universitaire, communautaire ou numérique. Catalogage selon les normes MARC21 et ISBD, indexation (Dewey, CDU), gestion du prêt et des retours, animation lecture et clubs de lecture, fonds numériques et logiciel PMB (gratuit). 10h de vidéos et attestation RIVO.', 3000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/171_bibliotheconomie-et-gestion-de-bibliotheque.pdf'),
('Muséologie et Conservation du Patrimoine', 'Préservez et mettez en valeur le patrimoine culturel.', 'Préservez et valorisez le patrimoine culturel matériel et immatériel africain. Conservation préventive et curative des collections (température, humidité, lumière, nuisibles), restauration d''''objets d''''art, conception d''''expositions, médiation culturelle et inventaire numérique du patrimoine. 15h de vidéos et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/172_museologie-et-conservation-du-patrimoine.pdf'),
('Gestion des ONG et Associations', 'Créez et gérez une association efficacement.', 'Créez et développez une ONG ou association en Afrique : statuts juridiques et enregistrement, gouvernance, recherche et gestion de subventions (UE, AFD, fondations), gestion de projets humanitaires, management du bénévolat et communication. 12h de vidéos, modèles de dossiers de financement et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/173_gestion-des-ong-et-associations.pdf'),
('Coopération Internationale et Développement', 'Travaillez dans l''''humanitaire et le développement.', 'Préparez votre carrière dans la coopération internationale et le développement : identification des bailleurs (PNUD, UE, AFD, Banque Mondiale), cycle de projet (identification, formulation, mise en oeuvre, évaluation), cadre logique, suivi-évaluation et rédaction de rapports. 15h de vidéos, templates et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/174_cooperation-internationale-et-developpement.pdf'),
('Relations Publiques et Communication Corporate', 'Gérez l''''image d''''une entreprise ou institution.', 'Maîtrisez les relations publiques et la communication institutionnelle. Relations avec les médias (communiqués de presse, conférences de presse, dossiers de presse), événements corporate, lobbying, communication de crise et management de la réputation en ligne. Exemples africains concrets. 12h de vidéos et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/175_relations-publiques-et-communication-corporate.pdf'),
('Démographie et Statistiques Sociales', 'Analysez les populations et leurs dynamiques.', 'Analysez les dynamiques de population : collecte et traitement des données démographiques (recensements, enquêtes), indicateurs clés (taux de natalité, mortalité, fécondité, migration), pyramides des âges, projections démographiques et politiques de population en Afrique. 12h de vidéos, données africaines ouvertes incluses et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/176_demographie-et-statistiques-sociales.pdf'),
('Criminologie et Sciences Forensiques', 'Comprenez le crime et les techniques d''''enquête.', 'Comprenez la criminologie et les sciences forensiques. Théories criminologiques, profiling criminel, techniques d''''enquête (relevés d''''empreintes, ADN forensique, balistique, analyse de scène de crime), expertises judiciaires et systèmes pénitentiaires africains. 15h de vidéos, études de cas africains et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/177_criminologie-et-sciences-forensiques.pdf'),
('Sécurité et Gestion des Risques', 'Protégez les personnes et les biens en entreprise.', 'Maîtrisez la gestion des risques en entreprise et dans les projets. Audit de sécurité, identification et évaluation des risques (AMDEC), élaboration d''''un plan de sécurité, gestion de crise, normes ISO 45001 (santé-sécurité) et ISO 31000 (management des risques). 15h de vidéos, templates et attestation RIVO.', 6000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/178_securite-et-gestion-des-risques.pdf'),
('Aéronautique et Pilotage d''''Avion Léger', 'Initiez-vous au pilotage d''''avion.', 'Initiez-vous au pilotage d''''avion léger (ULM et brevet PPL) : principes de l''''aérodynamique (portance, traînée, poussée, poids), cockpit et instruments de bord, navigation aérienne, météorologie aéronautique, réglementation africaine (ASECNA) et utilisation du simulateur de vol. 20h de vidéos et attestation RIVO.', 10000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/179_aeronautique-et-pilotage-davion-leger.pdf'),
('Navigation Maritime et Plaisance', 'Apprenez à naviguer sur un bateau.', 'Apprenez à naviguer sur voilier et bateau à moteur en sécurité. Lecture des cartes marines (SHOM), utilisation du compas et du GPS, signalisation maritime (bouées, phares), météo marine, manœuvres de port, règlement COLREG (anti-abordage) et permis côtier. 15h de vidéos et attestation RIVO.', 7000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/180_navigation-maritime-et-plaisance.pdf'),
('Plongée Sous-Marine et Apnée', 'Découvrez les fonds marins en toute sécurité.', 'Découvrez la plongée sous-marine et l''''apnée. Équipement de plongée (bouteille, régulateur, combinaison, masque, palmes), physique de la plongée (pression, narcose, décompression), techniques de descente et remontée, paliers de décompression, apnée statique et dynamique et faune marine africaine. 10h de vidéos et attestation RIVO.', 5000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/181_plongee-sous-marine-et-apnee.pdf'),
('Alpinisme et Escalade', 'Initiez-vous à l''''escalade et à la montagne.', 'Initiez-vous à l''''escalade et à la randonnée en montagne (Kilimandjaro, Atlas, Drakensberg). Nœuds d''''escalade (cabestan, huit, demi-cabestan), assurage (demi-tour, grigri), lecture de voies cotées, sécurité alpine et matériel (baudrier, corde, dégaines). 10h de vidéos, démonstrations et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/182_alpinisme-et-escalade.pdf'),
('Survie en Milieu Naturel', 'Apprenez à survivre en forêt, désert ou montagne.', 'Maîtrisez les techniques de survie en milieu naturel africain. Construire un feu sans allumettes (friction, feu par choc), fabriquer un abri avec des matériaux naturels, trouver et purifier de l''''eau, s''''orienter sans GPS, identifier les plantes comestibles et dangereuses, et signaler sa présence aux secours. 10h de vidéos terrain et attestation RIVO.', 4000, 'XOF', true, 'https://raw.githubusercontent.com/yelianj61-debug/afrocom-app/claude/sql-training-pdfs-mHfZm/afrocom-android/app/src/main/assets/pdfs/183_survie-en-milieu-naturel.pdf');